            expr.collect(&|e| Self::is_aggregate_function(e), &mut aggregates);
        }

        if let Some(expr) = having {
            expr.collect(&|e| Self::is_aggregate_function(e), &mut aggregates);
        }

        for (expr, _) in order_by {
            expr.collect(&|e| Self::is_aggregate_function(e), &mut aggregates);
        }

        aggregates
    }

