        let aggregates = self.collect_aggregates(&select, &having, &order_by);

        // Build GROUP BY and aggregate
        let mut node = from_node;
        let mut aggregate_scope = scope.spawn();

        if !group_by.is_empty() || !aggregates.is_empty() {
            // Build GROUP BY expressions
            let mut group_by_exprs = Vec::new();
            for expr in &group_by {
                group_by_exprs.push(self.build_expression(expr.clone(), &scope)?);
            }

            // Build aggregate expressions
            let mut agg_exprs = Vec::new();
            for expr in &aggregates {
                agg_exprs.push(self.build_expression(expr.clone(), &scope)?);
            }

            node = self.build_aggregate(node, group_by_exprs, agg_exprs, &mut aggregate_scope)?;
