            }
            Not(expr) => {
                let expr = Self::build_expression(*expr, scope)?;
                Ok(Expression::Not(Box::new(expr)))
            }
            Or(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Or(Box::new(lhs), Box::new(rhs)))
            }
            Equal(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Equal(Box::new(lhs), Box::new(rhs)))
            }
            GreaterThan(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::GreaterThan(Box::new(lhs), Box::new(rhs)))
            }
            GreaterThanOrEqual(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::GreaterThanOrEqual(Box::new(lhs), Box::new(rhs)))
            }
            Is(expr, lit) => {
                let expr = Self::build_expression(*expr, scope)?;
                let value = match lit {
                    ast::Literal::Null => Value::Null,
                    ast::Literal::Float(f) if f.is_nan() => Value::Float(f64::NAN),
                    _ => return errinput!("IS only supports NULL and NaN"),
                };
                Ok(Expression::Is(Box::new(expr), value))
            }
            LessThan(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::LessThan(Box::new(lhs), Box::new(rhs)))
            }
            LessThanOrEqual(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::LessThanOrEqual(Box::new(lhs), Box::new(rhs)))
            }
            NotEqual(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::NotEqual(Box::new(lhs), Box::new(rhs)))
            }
            Add(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Add(Box::new(lhs), Box::new(rhs)))
            }
            Divide(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Divide(Box::new(lhs), Box::new(rhs)))
            }
            Exponentiate(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Exponentiate(Box::new(lhs), Box::new(rhs)))
            }
            Factorial(expr) => {
                let expr = Self::build_expression(*expr, scope)?;
                Ok(Expression::Factorial(Box::new(expr)))
            }
            Identity(expr) => {
                let expr = Self::build_expression(*expr, scope)?;
                Ok(Expression::Identity(Box::new(expr)))
            }
            Multiply(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Multiply(Box::new(lhs), Box::new(rhs)))
            }
            Negate(expr) => {
                let expr = Self::build_expression(*expr, scope)?;
                Ok(Expression::Negate(Box::new(expr)))
            }
            Remainder(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Remainder(Box::new(lhs), Box::new(rhs)))
            }
            Subtract(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Subtract(Box::new(lhs), Box::new(rhs)))
            }
            Like(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Like(Box::new(lhs), Box::new(rhs)))
            }
        }
    }

    /// Builds a constant value from an AST expression by evaluating it.
    fn build_constant_value(expr: ast::Expression) -> Result<Value> {
        match expr {
            ast::Expression::Literal(lit) => {
                Ok(match lit {
                    ast::Literal::Null => Value::Null,
                    ast::Literal::Boolean(b) => Value::Boolean(b),
                    ast::Literal::Integer(i) => Value::Integer(i),
                    ast::Literal::Float(f) => Value::Float(f),
                    ast::Literal::String(s) => Value::String(s),
                })
            }
            _ => errinput!("expression must be constant"),
        }
    }
}

